package com.storemate.backend.web;
import com.storemate.backend.domain.*;import com.storemate.backend.repo.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import org.springframework.test.util.ReflectionTestUtils;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class ReportFeaturesIntegrationTest {
 @Autowired CategoryController categories;@Autowired InventoryOperationsController inventory;@Autowired InventoryController catalog;@Autowired StoreTemplateController templates;@Autowired WorkBreakController breaks;@Autowired StoreDetailsController details;@Autowired PayrollController payroll;@Autowired StoreTaskController tasks;@Autowired HandoverController handovers;@Autowired AccountRepository accounts;@Autowired StoreRepository stores;@Autowired StoreMemberRepository members;@Autowired ProductRepository products;@Autowired WorkSessionRepository sessions;@Autowired StoreTaskRepository taskRepo;@Autowired WorkShiftRepository shifts;
 Account owner,staff,other;Store store;StoreMember member;WorkSession work;
 @BeforeEach void setup(){String id=UUID.randomUUID().toString().substring(0,8);owner=accounts.save(new Account("report-o"+id,"unused",Role.OWNER,"사장","20000101"));staff=accounts.save(new Account("report-s"+id,"unused",Role.STAFF,"직원","20000101"));other=accounts.save(new Account("report-x"+id,"unused",Role.STAFF,"외부인","20000101"));store=stores.save(new Store("보고서 검증","카페",null,"테스트 주소",null,"09:00","22:00",id,owner));members.save(new StoreMember(owner,store,Role.OWNER,MemberStatus.APPROVED));member=members.save(new StoreMember(staff,store,Role.STAFF,MemberStatus.APPROVED));products.save(new Product(store,"REPORT-01","테스트 상품","음료",6,3,LocalDate.now().plusDays(10)));work=new WorkSession(staff,store);ReflectionTestUtils.setField(work,"clockIn",LocalDateTime.of(2026,10,5,9,0));ReflectionTestUtils.setField(work,"clockOut",LocalDateTime.of(2026,10,5,17,0));work.assignWage(10000,"CONFIRMED",owner);sessions.saveAndFlush(work);}
 InventoryOperationsController.Change out(int quantity,int expected,String key){return new InventoryOperationsController.Change(quantity,expected,"판매",null,null,key);}
 @Test void outboundIsAuditedAndRetryDoesNotRemoveTwice(){var r=out(2,6,"report-outbound-001");var first=inventory.outbound(staff,store.getId(),"REPORT-01",r);assertEquals(4,first.after());assertEquals(first.id(),inventory.outbound(staff,store.getId(),"REPORT-01",r).id());assertEquals(4,catalog.one(owner,store.getId(),"REPORT-01").stock());var history=inventory.history(owner,store.getId(),"REPORT-01",LocalDate.now(),LocalDate.now(),0);assertEquals("판매",history.getFirst().reason());assertEquals("OUT",history.getFirst().type());}
 @Test void outboundRejectsOverdraftAndConcurrentChanges(){assertThrows(ApiException.class,()->inventory.outbound(staff,store.getId(),"REPORT-01",out(7,6,"report-outbound-002")));assertThrows(ApiException.class,()->inventory.outbound(staff,store.getId(),"REPORT-01",out(1,5,"report-outbound-003")));assertEquals(6,catalog.one(owner,store.getId(),"REPORT-01").stock());}
 @Test void selectedLegacyBatchCanBeUsedForOutbound(){var r=new InventoryOperationsController.Change(2,6,"폐기",0L,0L,"report-batch-001");assertEquals(4,inventory.outbound(staff,store.getId(),"REPORT-01",r).after());assertEquals(4,catalog.batchList(owner,store.getId(),"REPORT-01").getFirst().quantity());}
 @Test void adjustmentIsOwnerOnlyAndRequiresReason(){assertThrows(ApiException.class,()->inventory.adjustment(staff,store.getId(),"REPORT-01",out(2,6,"report-adjust-001")));assertThrows(ApiException.class,()->inventory.adjustment(owner,store.getId(),"REPORT-01",new InventoryOperationsController.Change(2,6,"",null,null,"report-adjust-002")));assertEquals(2,inventory.adjustment(owner,store.getId(),"REPORT-01",out(2,6,"report-adjust-003")).after());}
 @Test void savedOrderPlanDoesNotChangeStockAndIsIdempotent(){inventory.metadata(owner,store.getId(),"REPORT-01",new InventoryOperationsController.Metadata("우유","240ml",12));var recommendation=inventory.recommendations(owner,store.getId()).getFirst();assertEquals(6,recommendation.quantity());var request=new InventoryOperationsController.PlanRequest("report-plan-001",List.of(new InventoryOperationsController.PlanLine("REPORT-01",4,6,12)));var saved=inventory.plan(owner,store.getId(),request);assertEquals(saved.id(),inventory.plan(owner,store.getId(),request).id());assertEquals(1,inventory.plans(owner,store.getId()).size());assertEquals(6,catalog.one(owner,store.getId(),"REPORT-01").stock());assertEquals("240ml",inventory.detail(staff,store.getId(),"REPORT-01").specification());}
 @Test void orderPlanRejectsStaffAndStaleInventory(){var request=new InventoryOperationsController.PlanRequest("report-plan-002",List.of(new InventoryOperationsController.PlanLine("REPORT-01",4,5,9)));assertThrows(ApiException.class,()->inventory.plan(staff,store.getId(),request));assertThrows(ApiException.class,()->inventory.plan(owner,store.getId(),request));assertThrows(ApiException.class,()->inventory.history(other,store.getId(),null,null,null,0));}
 @Test void templateCanBeCustomizedAndExamplesAreNotDuplicated(){var p=templates.get(owner,store.getId());assertTrue(p.categories().contains("원두"));var saved=templates.save(owner,store.getId(),new StoreTemplateController.Save("카페",true,List.of("원두","디저트"),List.of("마감 청소"),0,true));templates.save(owner,store.getId(),new StoreTemplateController.Save("카페",false,saved.categories(),saved.examples(),saved.revision(),true));assertEquals(1,taskRepo.findByStoreAndArchivedFalseOrderByIdDesc(store).size());assertFalse(templates.get(staff,store.getId()).expiryEnabled());assertThrows(ApiException.class,()->templates.save(staff,store.getId(),new StoreTemplateController.Save("기타",false,List.of("기타"),List.of(),0,false)));}
 @Test void breakTimeIsSharedWithRecordsAndBasePayroll(){var pause=new StatutoryPayCalculator.Pause(LocalDateTime.of(2026,10,5,12,0),LocalDateTime.of(2026,10,5,13,0));var saved=breaks.put(staff,store.getId(),work.getId(),new WorkBreakController.Save(0,List.of(pause)));assertEquals(3600,saved.seconds());assertEquals(3600,WageService.view(work).breakSeconds());assertEquals(70000,payroll.mine(staff,store.getId(),"2026-10").basePay());assertThrows(ApiException.class,()->breaks.put(staff,store.getId(),work.getId(),new WorkBreakController.Save(0,List.of())));assertThrows(ApiException.class,()->breaks.get(other,store.getId(),work.getId()));}
 @Test void breakTimeRejectsOverlapsAndChangesToFinalizedMonth(){var bad=new StatutoryPayCalculator.Pause(work.getClockIn().minusHours(1),work.getClockIn());assertThrows(ApiException.class,()->breaks.put(owner,store.getId(),work.getId(),new WorkBreakController.Save(0,List.of(bad))));payroll.finalizePay(owner,store.getId(),member.getId(),"2026-10",new PayrollController.Finalize(true,true,true));assertThrows(ApiException.class,()->breaks.put(owner,store.getId(),work.getId(),new WorkBreakController.Save(0,List.of())));}
 @Test void employeeContactAndScheduledDashboardUseStoreMemberName(){details.contact(owner,store.getId(),member.getId(),new StoreDetailsController.Contact("매장 이름","010-1234-5678"));assertEquals("매장 이름",details.contact(owner,store.getId(),member.getId()).name());shifts.save(new WorkShift(member,LocalDate.now(),"09:00","17:00"));assertEquals("매장 이름",details.scheduled(owner,store.getId()).getFirst().name());assertThrows(ApiException.class,()->details.contact(staff,store.getId(),member.getId()));}
 @Test void geofenceValidatesDistanceAccuracyAndFreshness(){store.details("매장","카페",null,"주소",null,"09:00","22:00",37.0,127.0,100);assertDoesNotThrow(()->StoreDetailsController.checkLocation(store,new Dto.ClockInRequest("QR",37.0,127.0,5.0,System.currentTimeMillis())));assertThrows(ApiException.class,()->StoreDetailsController.checkLocation(store,new Dto.ClockInRequest("QR",38.0,127.0,5.0,System.currentTimeMillis())));assertThrows(ApiException.class,()->StoreDetailsController.checkLocation(store,new Dto.ClockInRequest("QR",37.0,127.0,5.0,Long.MIN_VALUE)));assertThrows(ApiException.class,()->StoreDetailsController.checkLocation(store,new Dto.ClockInRequest("QR")));}
 @Test void handoverLinksTaskAndReadIsSeparateFromTaskCompletion(){var task=tasks.create(owner,store.getId(),new StoreTaskController.Create("report-task-001","테이블 정리","설명",false,member.getId()));var memo=handovers.create(staff,store.getId(),new Dto.HandoverRequest("다음 근무에서 확인해주세요",false,"미완료 전달",task.id()));assertEquals(task.id(),memo.relatedTaskId());var read=handovers.resolve(owner,store.getId(),memo.id(),new HandoverController.Resolve(true,memo.revision()));assertTrue(read.confirmedByMe());assertEquals("PENDING",read.relatedTaskStatus());assertEquals("미완료 전달",read.title());var edited=tasks.edit(owner,store.getId(),task.id(),new StoreTaskController.Edit(task.revision(),"좌석 정리","변경 내용",true));assertEquals("좌석 정리",edited.title());}

 @Test void customCategoryPersistsWithoutProductsAndRejectsStaff(){var initial=categories.get(owner,store.getId());var saved=categories.change(owner,store.getId(),new CategoryController.Change("ADD","스킨케어",null,initial.revision()));assertTrue(categories.get(staff,store.getId()).categories().contains("스킨케어"));assertTrue(saved.revision()>initial.revision());assertThrows(ApiException.class,()->categories.change(staff,store.getId(),new CategoryController.Change("ADD","메이크업",null,saved.revision())));assertThrows(ApiException.class,()->categories.get(other,store.getId()));}
 @Test void renameCategoryMovesExistingProductsWithoutChangingStock(){var current=categories.get(owner,store.getId());categories.change(owner,store.getId(),new CategoryController.Change("RENAME","음료","스킨케어",current.revision()));var product=catalog.one(owner,store.getId(),"REPORT-01");assertEquals("스킨케어",product.category());assertEquals(6,product.stock());assertFalse(categories.get(owner,store.getId()).categories().contains("음료"));}
 @Test void deleteCategoryKeepsProductsAndDoesNotReappear(){var current=categories.get(owner,store.getId());categories.change(owner,store.getId(),new CategoryController.Change("DELETE","음료",null,current.revision()));assertEquals("",catalog.one(owner,store.getId(),"REPORT-01").category());assertEquals(6,catalog.one(owner,store.getId(),"REPORT-01").stock());assertFalse(categories.get(owner,store.getId()).categories().contains("음료"));}
 @Test void categoryConflictsAndDuplicatesCannotOverwriteChanges(){var initial=categories.get(owner,store.getId());var saved=categories.change(owner,store.getId(),new CategoryController.Change("ADD","메이크업",null,initial.revision()));assertThrows(ApiException.class,()->categories.change(owner,store.getId(),new CategoryController.Change("ADD","메이크업",null,saved.revision())));assertThrows(ApiException.class,()->categories.change(owner,store.getId(),new CategoryController.Change("DELETE","음료",null,initial.revision())));assertThrows(ApiException.class,()->categories.change(owner,store.getId(),new CategoryController.Change("ADD","미분류",null,saved.revision())));assertEquals("음료",catalog.one(owner,store.getId(),"REPORT-01").category());}
 @Test void cosmeticAndClothingTemplatesHaveAppropriateCategories(){var preset=templates.presets(owner,store.getId());var cosmetic=preset.stream().filter(p->p.industry().equals("화장품")).findFirst().orElseThrow();assertTrue(cosmetic.categories().contains("스킨케어"));assertFalse(cosmetic.categories().contains("냉장"));assertFalse(preset.stream().filter(p->p.industry().equals("의류점")).findFirst().orElseThrow().expiryEnabled());}
}
